3	const MAX_CONTENT_LENGTH = 10000;
4	
5	interface ValidationSuccess {
6	  valid: true;
7	  data: IncomingMessage;
8	}
9	
10	interface ValidationFailure {
11	  valid: false;
12	  error: string;
13	}
14	
15	export type ValidationResult = ValidationSuccess | ValidationFailure;
16	
17	export function validateMessage(payload: unknown): ValidationResult {
18	  if (typeof payload !== 'object' || payload === null) {
19	    return {valid: false, error: 'Message must be an object'};
20	  }
21	
22	  const message = payload as Record<string, unknown>;
23	
24	  if (typeof message.type !== 'string') {
25	    return {valid: false, error: 'Message must have a type field'};
26	  }
27	
28	  switch (message.type) {
29	    case 'user_message':
30	      return validateUserMessage(message);
31	    case 'ping':
32	      return validatePingMessage(message);
33	    default:
34	      return {valid: false, error: `Unknown message type: ${message.type}`};
35	  }
36	}
37	
38	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
39	  if (typeof message.content !== 'string') {
40	    return {valid: false, error: 'user_message must have content string'};
41	  }
42	
43	  const trimmed = message.content.trim();
44	
45	  if (trimmed.length === 0) {
46	    return {valid: false, error: 'Message content cannot be empty'};
47	  }
48	
49	  if (message.content.length > MAX_CONTENT_LENGTH) {
50	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
51	  }
52	
53	  return {
54	    valid: true,
55	    data: {
56	      type: 'user_message',
57	      content: message.content,
58	    },
59	  };
60	}
61	
62	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
63	  if (typeof message.timestamp !== 'number') {
64	    return {valid: false, error: 'ping must have timestamp number'};
65	  }
66	
67	  return {
68	    valid: true,
69	    data: {
70	      type: 'ping',
71	      timestamp: message.timestamp,
72	    },
73	  };
74	}
