// A history request is not a turn: it answers here, off the lock, so it does not queue behind a streaming answer.
async function answerSessionList(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore: SessionStore | undefined
): Promise<void> {
  // An optional member answered as an empty list: a store of the five required members is a valid store, and its users have no list yet.
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }
